"""Session nine topic-specific teaching and handoff material."""
TITLES=['نمای کلی اعصاب گردن','شبکهٔ گردنی و شاخه‌های سطحی','قوس گردنی و شاخه‌های عمقی','اعصاب مغزی گردن و زوج نهم','شاخه‌های زوج نهم و شبکهٔ حلقی','عصب واگ در گردن','شاخه‌های حنجره‌ای و عصب راجعه','عصب اکسسوری','عصب زیرزبانی و مجاورات آن','تنهٔ سمپاتیک و گانگلیون فوقانی','گانگلیون‌های میانی و تحتانی','غدهٔ تیروئید و ایستموس','لوب‌های تیروئید و مجاورات','پاراتیروئید و عروق تیروئید']
GUIDES={
1:['سه گروه اعصاب گردن را در نمای قدامی از هم تفکیک کنید.','عصب فرنیک، واگ و قوس گردنی را نسبت به مهره‌ها پیدا کنید.','ورود اعصاب به بحث شبکه یا اعصاب مغزی را مشخص کنید.'],
2:['ریشه‌های C1 تا C4 را تا حلقه‌ها و شاخه‌های سطحی دنبال کنید.','شاخه‌های گوشی، پس‌سری، عرضی و فوق‌ترقوه‌ای را تفکیک کنید.','شاخه‌های جلدی را با شاخه‌های عضلانی مقایسه کنید.'],
3:['ریشه‌های بالا و پایین قوس گردنی را نسبت به غلاف کاروتید نشان دهید.','رشته‌های C1 همراه XII را از خود XII تفکیک کنید.','فرنیک را روی اسکالن قدامی تا ورودی سینه دنبال کنید.'],
4:['مسیر IX از ساقهٔ مغز و سوراخ ژوگولار را دنبال کنید.','زوج‌های IX، X و XI را در کنار XII مقایسه کنید.','استایلوفارنژیوس و شاخه‌های حسی حلق را در نما بیابید.'],
5:['مسیر پاراسمپاتیک پاروتید را از IX تا گانگلیون اوتیک دنبال کنید.','شاخه‌های حلقی، کاروتیدی، لوزه‌ای و زبانی IX را تفکیک کنید.','نقش اجزای شبکهٔ حلقی را با منبع مقایسه کنید.'],
6:['واگ را در غلاف کاروتید و در ریشهٔ گردن دنبال کنید.','شاخه‌های گوشی، مننژی و حلقی را از شاخه‌های حنجره‌ای جدا کنید.','مسیر واگ راست و چپ را نسبت به رگ‌ها مقایسه کنید.'],
7:['شاخهٔ داخلی و خارجی حنجره‌ای فوقانی را با کارکردشان تفکیک کنید.','مسیر راجعهٔ چپ زیر قوس و راست زیر ساب‌کلاوین را دنبال کنید.','مجاورت عصب راجعه و تیروئیدی تحتانی را با توجه به تنوع بخوانید.'],
8:['ریشه‌های توصیف‌شدهٔ XI و مسیر نخاعی آن را از سوراخ‌ها دنبال کنید.','مسیر عصب را در مثلث خلفی بین استرنوکلئیدوماستوئید و تراپزیوس مشخص کنید.','حرکت و حس عمقی را در ارتباط با اعصاب گردنی تفکیک کنید.'],
9:['XII را روی هیوگلوس تا زبان دنبال کنید.','ساختارهای سطحی هیوگلوس را از لینگوال و زوج IX در عمق جدا کنید.','رشته‌های C1 همراه XII را از شاخه‌های ذاتی آن متمایز کنید.'],
10:['تنهٔ سمپاتیک را در پشت غلاف کاروتید نشان دهید.','گانگلیون فوقانی و شاخه‌های کاروتیدی و حلقی را روی شکل بیابید.','سطح پیش‌عقده‌ای و اتصال پس‌عقده‌ای را از هم جدا کنید.'],
11:['گانگلیون میانی و ستاره‌ای را نسبت به C6 و دندهٔ اول بیابید.','قوس ساب‌کلاوین را دور شریان دنبال کنید.','شاخه‌های خاکستری و قلبی و شبکهٔ ورتبرال را تفکیک کنید.'],
12:['دو لوب و ایستموس را نسبت به غضروف و حلقه‌های نای نشان دهید.','کپسول و بافت غده را از غلاف فاسیایی جدا کنید.','هورمون‌های نام‌برده را از عروق و مجاورات تفکیک کنید.'],
13:['سطوح و کناره‌های لوب تیروئید را با مجاوراتشان مشخص کنید.','لوب هرمی و مجرای تیروگلوسال را از ایستموس جدا بشناسید.','عصب راجعه و غدد پاراتیروئید را نسبت به سطح خلفی دنبال کنید.'],
14:['تیروئیدی فوقانی و تحتانی و آناستوموزهای آن‌ها را در دو نما بیابید.','عصب راجعه و پاراتیروئیدها را در نمای خلفی دنبال کنید.','تخلیهٔ وریدهای فوقانی، میانی و تحتانی را مقایسه کنید.']}
QUESTIONS={i:'؛ '.join(x.rstrip(' .') for x in v[:2])+'؟' for i,v in GUIDES.items()}
REF={1:('نتر، اطلس آناتومی انسان، ویراست ۸، پلیت ۵۷، صفحهٔ فایل ۱۰۹','نقشهٔ اعصاب را با شاخه‌های سطحی و عمقی مقایسه کنید.'),2:('گری، آناتومی برای دانشجویان، ویراست ۳، صفحهٔ فایل ۵۶، چاپی ۱۰۲۸، شکل ۸.۱۸۴؛ نتر، پلیت ۱۵۶، صفحهٔ فایل ۲۰۸','شبکه از شاخه‌های قدامی C1 تا C4 ساخته می‌شود؛ فرنیک سهم C3 تا C5 دارد.'),3:('نتر، پلیت ۵۷، صفحهٔ فایل ۱۰۹؛ گری، صفحهٔ فایل ۵۶، چاپی ۱۰۲۸','رشته‌های C1 همراه عصب زیرزبانی را با دو ریشهٔ آنسا مقایسه کنید.'),4:('گری، صفحهٔ فایل ۴۲، چاپی ۱۰۱۴، شکل ۸.۱۶۸؛ نتر، پلیت ۱۵۲، صفحهٔ فایل ۲۰۴','در گری IX به استایلوفارنژیوس، سینوس کاروتید و حلق شاخه می‌دهد؛ محل و نوع حس گانگلیون‌ها در عبارت درس جداگانه بررسی شود.'),5:('نتر، پلیت ۱۵۲، صفحهٔ فایل ۲۰۴','مسیر پیش‌عقده‌ای تا اوتیک و مسیر پس‌عقده‌ای به پاروتید را در شکل دنبال کنید؛ متن منبع و نمودار را از هم متمایز بخوانید.'),6:('گری، صفحهٔ فایل ۴۲، چاپی ۱۰۱۴، شکل ۸.۱۶۹؛ نتر، پلیت ۱۵۳، صفحهٔ فایل ۲۰۵','گری واگ را پشت شریان و در داخل غلاف کاروتید نشان می‌دهد.'),7:('نتر، پلیت ۱۵۳، صفحهٔ فایل ۲۰۵؛ پلیت ۱۰۴، صفحهٔ فایل ۱۵۶','رابطهٔ عصب راجعه و عروق می‌تواند متغیر باشد؛ عبارت مطلق و پیامد بالینی در اصل را حکم همگانی یا دستور جراحی فرض نکنید.'),8:('نتر، پلیت ۱۵۴، صفحهٔ فایل ۲۰۶؛ گری، صفحهٔ فایل ۵۶، چاپی ۱۰۲۸','مسیر شاخهٔ نخاعی در مثلث خلفی و آسیب‌پذیری آن را در نما مقایسه کنید؛ اصطلاح ریشهٔ جمجمه‌ای به قرارداد منبع وابسته است.'),9:('نتر، پلیت ۱۵۵، صفحهٔ فایل ۲۰۷','رشته‌های C1 و شاخه‌های زبانی XII را با عضلات و هیوگلوس مقایسه کنید.'),10:('گری، صفحهٔ فایل ۶۴، چاپی ۱۰۳۶، شکل ۸.۱۹۰؛ نتر، پلیت ۱۵۷، صفحهٔ فایل ۲۰۹','گری مسیر پیش‌عقده‌ای صعودی از بخش فوقانی نخاع سینه‌ای را از شاخه‌های خاکستری گردنی جدا می‌کند.'),11:('گری، صفحهٔ فایل ۶۴، چاپی ۱۰۳۶، شکل ۸.۱۹۰','اتصال گانگلیون تحتانی به اولین گانگلیون سینه‌ای و قوس زیرترقوه‌ای را روی شکل بررسی کنید.'),12:('نتر، پلیت ۱۰۳، صفحهٔ فایل ۱۵۵','در نمای قدامی نتر، ایستموس و دو لوب را نسبت به لامی و نای بیابید.'),13:('نتر، پلیت ۱۰۴، صفحهٔ فایل ۱۵۶؛ گری، صفحهٔ فایل ۴۷، چاپی ۱۰۱۹','تصویر خلفی پاراتیروئید و عصب راجعه را نشان می‌دهد. توصیف جراحی اصل دستور عمل جراحی نیست.'),14:('گری، صفحهٔ فایل ۴۷، چاپی ۱۰۱۹، شکل‌های ۸.۱۷۵ و ۸.۱۷۶؛ نتر، پلیت ۱۰۴، صفحهٔ فایل ۱۵۶','گری شریان‌های تیروئیدی و تنوع شریان ima را نشان می‌دهد؛ درصدها و مجاورات ثابت‌انگاشته‌شده در اصل به همهٔ افراد تعمیم ندارند.')}
